// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 t) public {
        uint256 t1 = bound(t, 1, type(uint256).max - 1);
        // first call at time t1: on the reference it succeeds and sets pastBlockTime = t1
        vm.warp(t1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        // second call strictly later must also succeed: block.timestamp > pastBlockTime
        vm.warp(t1 + 1);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok2, "a call strictly later than the last accepted timestamp must succeed");
    }
}
